'use strict';
const EXP_KEY='prompt-lab-experiments-v1';
let experiments={draft:{task:'도서관 독서 모임을 소개해 줘.',paragraphs:2,perParagraph:2,total:4,style:'요',example:'독서 모임을 열어요. 토요일에 만나요.\n\n책을 가져오세요. 댓글로 신청해 주세요.',skeleton:'[소개 문장]. [일시 문장].\n\n[준비물 문장]. [신청 문장].',reason:'',repeats:1},versions:[],runs:[]};
let expBusy=false,expStop=false,expToken='',expModels=[],expModel='',expSelected='',expRecoveryRaw='';
experiments.manualDraft=Object.assign({text:'',model:'',condition:'plain'},experiments.manualDraft||{});
const expTime=()=>new Date().toISOString();
const expId=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
function experimentErrorMessage(e,fallback){if(e?.name==='SyntaxError')return '응답이나 백업의 JSON 형식을 읽지 못했습니다. 파일이나 연결 상태를 확인해 주세요.';if(['TimeoutError','AbortError'].includes(e?.name))return '정해진 시간 안에 응답을 받지 못했습니다. 연결 상태와 실행 기록을 확인해 주세요. 자동으로 다시 시도하지 않습니다.';return typeof e?.message==='string'&&/[가-힣]/.test(e.message)?e.message:fallback;}
function saveExperiments(){try{localStorage.setItem(EXP_KEY,JSON.stringify(experiments));return true;}catch{notify('실험 기록을 저장하지 못했습니다. 실험 백업을 내려받아 주세요.');return false;}}
function experimentProblems(d){const errors=[];for(const k of ['paragraphs','perParagraph','total'])if(!Number.isInteger(d?.[k])||d[k]<1||d[k]>20)errors.push('문단 수와 문장 수는 1~20 사이의 정수로 입력해 주세요.');if(!d||d.paragraphs*d.perParagraph!==d.total)errors.push('문단 수에 문단마다 넣을 문장 수를 곱한 값이 전체 문장 수와 같아야 합니다.');if(typeof d?.task!=='string'||!d.task.trim())errors.push('과제를 작성해 주세요.');if(typeof d?.example!=='string'||!d.example.trim()||typeof d?.skeleton!=='string'||!d.skeleton.trim())errors.push('비교할 예시와 빈 틀을 모두 작성해 주세요.');if(!['요','합니다'].includes(d?.style))errors.push('말투를 선택해 주세요.');if(!Number.isInteger(d?.repeats)||d.repeats<1||d.repeats>3)errors.push('각 요청 방식의 실행 횟수는 1~3회로 정해 주세요.');return errors;}
function experimentPrompts(d){const common=`${d.task}\n\n요구사항:\n- ${d.paragraphs}문단\n- 문단마다 ${d.perParagraph}문장\n- 전체 ${d.total}문장\n- ${d.style==='요'?'해요체':'합니다체'}\n- 소제목 없이 본문만 작성`;
return {plain:common,example:common+'\n\n참고 예시:\n'+d.example,skeleton:common+'\n\n빈 틀(대괄호를 내용으로 채우세요):\n'+d.skeleton};}
function inspectExperimentText(text,d){
 const raw=String(text||'').trim(),blocks=raw?raw.split(/\n\s*\n/):[];
 const sentences=blocks.map(b=>b.replace(/(^|\s)[QA]\.\s*/g,'$1').replace(/(\d)\.(\d)/g,'$1∯$2').match(/[^.!?]+[.!?]+(?:["”’']*)/g)||[]);
 const ambiguous=!raw||blocks.some((b,i)=>!/[.!?]["”’']*\s*$/.test(b)||!sentences[i].length)||/[“”「」]/.test(raw);
 const ends=sentences.flat().map(s=>s.trim().replace(/[.!?"”’'\s]+$/g,''));
 const good=d.style==='요'?/요$/:/(니다|십시오)$/;
 const bad=d.style==='요'?/(니다|십시오)$/:/요$/;
 const style=ambiguous?null:ends.some(s=>bad.test(s))?false:ends.every(s=>good.test(s))?true:null;
 return [{label:'문단 수',pass:raw?blocks.length===d.paragraphs:null,detail:`${blocks.length} / ${d.paragraphs}`},{label:'문단별 문장 수',pass:ambiguous?null:sentences.every(s=>s.length===d.perParagraph),detail:sentences.map(s=>s.length).join(', ')},{label:'전체 문장 수',pass:ambiguous?null:ends.length===d.total,detail:`${ends.length} / ${d.total}`},{label:'말투',pass:style,detail:'문장 끝 표현을 검사합니다. 애매한 표현은 확인 필요로 남깁니다.'}];
}
const EXP_STATUS_NAMES={completed:'완료',error:'오류',incomplete:'미완료',pending:'응답 대기 중'};
const EXP_NAMES={plain:'지시만',example:'지시와 완성 예시',skeleton:'지시와 빈 틀'};
// Validate stored data before it reaches renderers; keep malformed raw storage
// available for recovery and start with the safe defaults in memory.
try{const raw=localStorage.getItem(EXP_KEY);if(raw){expRecoveryRaw=raw;const x=JSON.parse(raw);experiments=validateExperimentBackup({...x,schema:EXP_KEY});expRecoveryRaw='';}}catch{experiments.loadWarning=true;}
function freezeExperiment(){const d=JSON.parse(JSON.stringify(experiments.draft)),errors=experimentProblems(d);if(errors.length)return {errors};const prompts=experimentPrompts(d);if(Object.values(prompts).some(s=>s.length>12000))return {errors:['세 방식의 프롬프트는 각각 12,000자 이하여야 합니다.']};const v={id:expId(),at:expTime(),draft:d,prompts};experiments.versions.push(v);expSelected=v.id;const stored=saveExperiments();return {version:v,stored};}
function expResults(v){return experiments.runs.filter(r=>r.version===v.id);}
function expSummary(v){const runs=expResults(v);return Object.keys(EXP_NAMES).map(condition=>{const all=runs.filter(r=>r.condition===condition),complete=all.filter(r=>r.status==='completed'),judged=complete.filter(r=>r.flags.every(f=>f.pass!==null));return {condition,attempts:all.length,complete:complete.length,judged:judged.length,unknown:complete.length-judged.length,mean:judged.length?judged.reduce((n,r)=>n+r.flags.filter(f=>f.pass).length,0)/(judged.length*4):null,full:judged.length?judged.filter(r=>r.flags.every(f=>f.pass)).length/judged.length:null};});}
function expField(k,label,type='text'){const d=experiments.draft;return `<label class="field" for="exp-${k}">${label}</label>${type==='area'?`<textarea id="exp-${k}" maxlength="8000" data-exp="${k}" ${expBusy?'disabled':''}>${esc(d[k])}</textarea>`:`<input id="exp-${k}" type="${type}" ${type==='number'?'min="1" max="20"':''} value="${esc(d[k])}" data-exp="${k}" ${expBusy?'disabled':''}>`}`;}
function renderExperiment(){const apiOpen=expBusy||Boolean(document.querySelector?.('#api-panel')?.open);const d=experiments.draft,v=experiments.versions.find(x=>x.id===expSelected)||experiments.versions.at(-1),errors=experimentProblems(d),exampleFlags=inspectExperimentText(d.example,d);
 $('#main').innerHTML=`<section class="hero"><div><p class="eyebrow">나의 실험</p><h1>프롬프트를 바꾸면 응답도 달라질까요?</h1><p>같은 과제를 지시만으로 요청해 보고, 완성 예시나 빈 틀을 더해서도 요청해 보세요. 세 방식으로 받은 답이 조건을 얼마나 잘 지켰는지 비교할 수 있습니다.</p></div></section><div class="pair"><section class="card"><h2>1. 과제와 조건 정하기</h2>${expField('task','AI에게 맡길 과제','area')}<div class="row">${expField('paragraphs','문단 수','number')}${expField('perParagraph','문단마다 넣을 문장 수','number')}${expField('total','전체 문장 수','number')}</div><label class="field" for="exp-style">말투</label><select id="exp-style" ${expBusy?'disabled':''}><option value="요" ${d.style==='요'?'selected':''}>해요체</option><option value="합니다" ${d.style==='합니다'?'selected':''}>합니다체</option></select>${expField('example','비교에 사용할 완성 예시','area')}${expField('skeleton','비교에 사용할 빈 틀','area')}${expField('reason','이번에 바꾼 부분과 이유','area')}<button id="exp-inspect" ${expBusy?'disabled':''}>조건 확인</button><div id="exp-validation" role="status">${errors.length?`<div class="result warning">${errors.map(e=>`<p>${esc(e)}</p>`).join('')}</div>`:'<p class="result">문단 수와 문장 수가 서로 맞습니다.</p>'}<p class="note">완성 예시 검사: ${exampleFlags.map(f=>`${esc(f.label)} ${f.pass===null?'확인 필요':f.pass?'맞음':'어긋남'}`).join(' · ')}. 지시와 어긋나는 예시가 답에 어떤 영향을 주는지 알아보고 싶다면, 어긋난 부분을 일부러 남겨 두고 비교해도 됩니다.</p></div><button id="exp-freeze" ${expBusy?'disabled':''}>비교안 저장</button></section><details class="card api-panel" id="api-panel"><summary>선택 기능: API로 직접 실행하기 (유료)</summary><h2>API로 직접 실행하기</h2><p>지금은 OpenAI API만 지원합니다. API 키는 서버의 환경 변수에만 넣고, 이 화면에는 넣지 않습니다. 아래 칸에는 서버를 설정할 때 정한 실험 비밀번호를 입력해 주세요.</p><label class="field" for="exp-token">실험 비밀번호 (저장하지 않습니다)</label><input id="exp-token" type="password" autocomplete="off" ${expBusy?'disabled':''}><button id="exp-connect" ${expBusy?'disabled':''}>연결 확인 (요금이 발생하지 않습니다)</button><label class="field" for="exp-model">실행 모델</label><select id="exp-model" ${expBusy?'disabled':''}>${expModels.length?expModels.map(m=>`<option ${m===expModel?'selected':''}>${esc(m)}</option>`).join(''):'<option value="">먼저 연결을 확인해 주세요</option>'}</select><label class="field" for="exp-repeats">각 요청 방식을 실행할 횟수</label><select id="exp-repeats" ${expBusy?'disabled':''}>${[1,2,3].map(n=>`<option ${d.repeats===n?'selected':''}>${n}</option>`).join('')}</select><p id="exp-cost">한 번 실행하면 API를 모두 ${d.repeats*3}번 호출합니다. 호출마다 출력은 최대 1,200토큰이며, 요금은 모델과 실제 사용량에 따라 달라집니다. 프롬프트는 OpenAI로 전송됩니다.</p><p>세 방식을 실행하는 순서는 무작위로 정합니다. 과제와 형식 조건, 모델, 출력 길이 제한은 같게 유지합니다. 실패한 요청은 자동으로 다시 시도하지 않습니다.</p><div class="actions"><button class="primary" id="exp-run" ${expBusy?'disabled':''}>입력한 조건으로 유료 실험 실행</button><button id="exp-stop" ${!expBusy?'disabled':''}>다음 호출부터 중단</button></div><p id="exp-progress" role="status">${expBusy?'실행 중입니다. 현재 호출은 끝까지 받은 뒤 저장합니다.':'1번에 입력한 조건을 새 비교안으로 저장한 뒤 실행합니다. 실행하기 전에 요금이 발생한다는 점을 한 번 더 확인합니다.'}</p><p class="note">HTML 파일을 직접 열었을 때는 API를 호출할 수 없습니다. 서버에서 실행하거나 Vercel에 배포한 주소에서 열어 주세요.</p></details></div><section class="card"><h2>2. 비교안과 결과</h2><label class="field" for="exp-version">비교안 이력</label><select id="exp-version">${experiments.versions.map((x,i)=>`<option value="${esc(x.id)}" ${x.id===v?.id?'selected':''}>${i+1}번 · ${esc(new Date(x.at).toLocaleString('ko-KR'))}</option>`).join('')}</select><div id="exp-results">${v?renderExperimentResults(v):'<p>비교안을 저장하면 프롬프트와 결과를 여기에서 볼 수 있습니다.</p>'}</div></section><section class="card"><h2>3. 응답을 직접 가져오기</h2><p>선택한 비교안의 프롬프트를 다른 AI 서비스에서 실행했다면, 받은 답을 여기에 붙여 넣어 보세요. API로 받은 답과는 구분해서 저장됩니다.</p><label for="exp-manual-condition">응답을 받을 때 사용한 전달 방식</label><select id="exp-manual-condition">${Object.entries(EXP_NAMES).map(([k,n])=>`<option value="${k}">${n}</option>`).join('')}</select><label class="field" for="exp-manual-model">실행한 모델 (직접 입력)</label><input id="exp-manual-model" type="text" maxlength="100"><label class="field" for="exp-manual">응답 붙여 넣기</label><textarea id="exp-manual" maxlength="20000"></textarea><label class="field" for="exp-import-text">또는 TXT 파일 불러오기</label><input id="exp-import-text" type="file" accept=".txt,text/plain"><button id="exp-add">선택한 비교안에 응답 저장</button></section><div class="actions"><button id="exp-export">전체 실험 백업 JSON</button><button id="exp-csv">선택한 비교안 결과 CSV</button></div><p class="note">실험 기록도 이 브라우저에 저장됩니다. 다른 곳으로 옮기려면 학습 백업과 별도로 ‘전체 실험 백업’을 내려받아 주세요. 비교안과 응답, 실패 기록을 함께 보관할 수 있습니다. 다만 응답 내용이 사실인지는 자동으로 확인하지 않으므로 직접 살펴봐야 합니다.</p>`;
 if($('#api-panel'))$('#api-panel').open=apiOpen;bindManualDraft();
 bindExperimentExtras();
 document.querySelectorAll('[data-exp]').forEach(el=>el.oninput=()=>{d[el.dataset.exp]=el.type==='number'?Number(el.value):el.value;saveExperiments();});
 $('#exp-style').onchange=e=>{d.style=e.target.value;saveExperiments();};$('#exp-repeats').onchange=e=>{d.repeats=Number(e.target.value);saveExperiments();$('#exp-cost').textContent=`한 번 실행하면 API를 모두 ${d.repeats*3}번 호출합니다. 호출마다 출력은 최대 1,200토큰이며, 요금은 모델과 실제 사용량에 따라 달라집니다. 프롬프트는 OpenAI로 전송됩니다.`;};
 $('#exp-token').value=expToken;$('#exp-token').oninput=e=>{expToken=e.target.value;};$('#exp-model').onchange=e=>expModel=e.target.value;
 $('#exp-inspect').onclick=()=>{const errors=experimentProblems(d),flags=inspectExperimentText(d.example,d);$('#exp-validation').innerHTML=(errors.length?errors.map(e=>`<p class="result warning">${esc(e)}</p>`).join(''):'<p class="result">문단 수와 문장 수가 서로 맞습니다.</p>')+`<p class="note">완성 예시 검사: ${flags.map(f=>`${esc(f.label)} ${f.pass===null?'확인 필요':f.pass?'맞음':'어긋남'}`).join(' · ')}</p>`;};$('#exp-freeze').onclick=()=>{const x=freezeExperiment();if(x.errors){notify(x.errors.join(' '));return;}renderExperiment();notify(x.stored?'비교안을 저장했습니다. 아래 비교안 이력에서 확인할 수 있습니다.':'화면에 비교안을 만들었지만 저장하지 못했습니다. 전체 실험 백업을 내려받아 주세요.');};
 $('#exp-connect').onclick=async()=>{try{if(location.protocol==='file:')throw Error('서버 또는 배포한 주소에서 열어 주세요.');const r=await fetch('/api/experiment',{headers:{Authorization:'Bearer '+expToken}}),j=await r.json();if(!r.ok)throw Error(j.error);expModels=j.models;expModel=expModels[0];if(page==='experiment')renderExperiment();notify('서버 설정을 확인했습니다. 아직 AI를 호출하지 않았습니다.');}catch(e){notify(experimentErrorMessage(e,'서버에 연결하지 못했습니다. 인터넷 연결과 서버 설정을 확인해 주세요.'));}};
 $('#exp-run').onclick=runExperiment;$('#exp-stop').onclick=()=>{expStop=true;$('#exp-progress').textContent='현재 호출이 끝나면 중단합니다. 이미 시작한 호출에는 비용이 발생할 수 있습니다.';};
 $('#exp-version').onchange=e=>{expSelected=e.target.value;renderExperiment();};
 $('#exp-import-text').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>60000){notify('TXT 파일은 60KB 이하여야 합니다.');return;}const t=await f.text();if(t.length>20000){notify('응답은 20,000자 이하여야 합니다.');return;}experiments.manualDraft.text=t;saveExperiments();if($('#exp-manual'))$('#exp-manual').value=t;};
 $('#exp-add').onclick=()=>{if(!v){notify('먼저 비교안을 저장해 주세요.');return;}const text=$('#exp-manual').value.trim(),model=$('#exp-manual-model').value.trim();if(!text||!model){notify('응답과 실행 모델을 적어 주세요.');return;}experiments.runs.push({id:expId(),version:v.id,condition:$('#exp-manual-condition').value,source:'manual',status:'completed',model,text,at:expTime(),flags:inspectExperimentText(text,v.draft)});experiments.manualDraft.text='';const stored=saveExperiments();renderExperiment();notify(stored?'응답과 검사 결과를 추가했습니다.':'화면에 응답을 추가했지만 저장하지 못했습니다. 전체 실험 백업을 내려받아 주세요.');};
 $('#exp-export').onclick=()=>download('prompt-lab-experiments.json',JSON.stringify({schema:EXP_KEY,...experiments},null,2),'application/json');
 $('#exp-csv').onclick=()=>{if(!v){notify('먼저 비교안을 저장해 주세요.');return;}const rows=[['condition','source','model','status','paragraphs','per_paragraph','total','style','time'],...expResults(v).map(r=>[r.condition,r.source,r.model,r.status,...(r.flags||Array(4).fill({pass:null})).map(f=>f.pass===null?'unknown':f.pass),r.at])];download('experiment-results.csv','\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv');};
}
function bindManualDraft(){const m=experiments.manualDraft;for(const [id,key] of [['exp-manual','text'],['exp-manual-model','model'],['exp-manual-condition','condition']]){const el=$('#'+id);el.value=m[key];el[el.tagName==='SELECT'?'onchange':'oninput']=()=>{m[key]=el.value;saveExperiments();};}}
function renderExperimentResults(v){const all=expResults(v),previous=experiments.versions[experiments.versions.findIndex(x=>x.id===v.id)-1];return `<p>바꾼 부분과 이유: ${esc(v.draft.reason||'기록하지 않음')}</p>${previous?`<details><summary>바로 이전 비교안과 달라진 부분</summary>${['task','paragraphs','perParagraph','total','style','example','skeleton'].filter(k=>previous.draft[k]!==v.draft[k]).map(k=>`<h4>${esc(({task:'과제',paragraphs:'문단 수',perParagraph:'문단별 문장 수',total:'전체 문장 수',style:'말투',example:'예시',skeleton:'빈 틀'})[k])}</h4><pre class="response">이전: ${esc(previous.draft[k])}\n현재: ${esc(v.draft[k])}</pre>`).join('')||'<p>이전 비교안과 달라진 부분이 없습니다.</p>'}</details>`:''}${Object.entries(v.prompts).map(([k,p])=>`<details><summary>${EXP_NAMES[k]} · 실제로 보낼 프롬프트</summary><pre class="response">${esc(p)}</pre></details>`).join('')}<div class="tablewrap"><table><thead><tr><th>전달 방식</th><th>전체 기록 / 완료된 응답</th><th>자동 검사한 응답</th><th>평균 규칙 준수율</th><th>모든 조건을 지킨 응답의 비율</th></tr></thead><tbody>${expSummary(v).map(s=>`<tr><th>${EXP_NAMES[s.condition]}</th><td>${s.attempts} / ${s.complete}</td><td>${s.judged}개 (확인 필요 ${s.unknown}개)</td><td>${s.mean===null?'—':(s.mean*100).toFixed(1)+'%'}</td><td>${s.full===null?'—':(s.full*100).toFixed(1)+'%'}</td></tr>`).join('')}</tbody></table></div><p class="note">두 비율은 끝까지 생성된 응답 가운데, 조건 4개를 모두 자동으로 검사할 수 있는 응답만으로 계산합니다. 평균 규칙 준수율은 통과한 검사 수를 전체 검사 수로 나눈 값이고, 모든 조건을 지킨 응답의 비율은 조건을 하나도 어기지 않은 응답 수를 검사한 응답 수로 나눈 값입니다. 확인이 필요한 응답과 오류, 미완료 기록은 계산에서 빼고 따로 표시합니다. 그래서 확인이 필요한 응답이 많으면 비율이 한쪽으로 치우칠 수 있습니다. 직접 가져온 응답이나 다른 모델의 응답이 섞여 있다면, 합친 비율만 보고 어느 프롬프트가 낫다고 판단하지 마세요.</p>${new Set(all.filter(r=>r.status==='completed').map(r=>r.model+'|'+r.source)).size>1?'<p class="result warning">모델이나 응답을 가져온 방법이 서로 다릅니다. 합친 비율만으로 전달 방식의 효과를 판단하지 마세요.</p>':''}${experimentGroups(v)}${experimentReview(all)}${all.map(r=>`<details><summary>${EXP_NAMES[r.condition]} · ${esc(r.model)} · ${esc(EXP_STATUS_NAMES[r.status]||"확인 필요")} · ${r.source==='api'?'API 응답':'직접 입력'}</summary><p class="note">${esc(r.at)} · 실행 회차 ${esc(r.batch||'직접 입력')} · ${r.usage?'토큰 '+esc(r.usage.total_tokens):'토큰 정보 없음'}</p><pre class="response">${esc(r.text||r.error||'')}</pre>${(r.flags||[]).map(f=>`<p>${esc(f.label)}: <strong>${f.pass===null?'확인 필요':f.pass?'지킴':'어김'}</strong> · ${esc(f.detail)}</p>`).join('')}${manualReviewUI(r)}${r.status==='incomplete'?'<p>응답이 끝까지 생성되지 않았으므로 준수율 계산에 포함하지 않습니다.</p>':''}</details>`).join('')}<p class="note">자동 검사는 빈 줄을 문단의 경계로, 마침표와 물음표, 느낌표를 문장의 끝으로 봅니다. 약어나 복잡한 인용문이 있으면 직접 확인해 주세요. 말투 검사도 문장 끝 표현만 보는 보조 검사입니다.</p>`;}
async function runExperiment(){if(expBusy)return;if(!expToken||!expModel){notify('먼저 연결을 확인해 주세요.');return;}const errors=experimentProblems(experiments.draft);if(errors.length){notify(errors.join(' '));return;}const n=experiments.draft.repeats*3;if(!confirm(`과제와 예시, 빈 틀을 OpenAI로 보내고, 요금이 발생하는 호출을 모두 ${n}번 실행합니다. 호출마다 출력은 최대 1,200토큰입니다. 실행할까요?`))return;
 const frozen=freezeExperiment();if(frozen.errors){notify(frozen.errors.join(' '));return;}if(!frozen.stored){notify('비교안을 저장하지 못해 실행하지 않았습니다. 실험 백업을 내려받고 저장 공간을 확인해 주세요.');return;}const v=frozen.version,model=expModel,token=expToken,batch=expId(),jobs=[];for(let i=0;i<v.draft.repeats;i++)jobs.push(...Object.keys(EXP_NAMES));for(let i=jobs.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[jobs[i],jobs[j]]=[jobs[j],jobs[i]];}
 v.plan={batch,model,order:jobs,maxOutputTokens:1200,provider:'OpenAI',started:expTime()};expBusy=true;expStop=false;saveExperiments();renderExperiment();
 try{for(let i=0;i<jobs.length&&!expStop;i++){const condition=jobs[i],record={id:expId(),version:v.id,condition,batch,source:'api',model,at:expTime(),status:'pending'};experiments.runs.push(record);saveExperiments();if(page==='experiment')$('#exp-progress').textContent=`${i+1} / ${jobs.length} · ${EXP_NAMES[condition]} 응답을 기다립니다.`;
 try{const r=await fetch('/api/experiment',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify({model,prompt:v.prompts[condition]}),signal:AbortSignal.timeout(65000)}),j=await r.json();if(!r.ok)throw Error(j.error||'API 요청 실패');Object.assign(record,j);if(j.status==='completed')record.flags=inspectExperimentText(j.text,v.draft);}catch(e){record.status='error';record.error=experimentErrorMessage(e,'응답을 받지 못했습니다. 연결 상태와 서버 설정을 확인해 주세요. 자동으로 다시 시도하지 않습니다.');expStop=true;}saveExperiments();}
 }finally{v.plan.finished=expTime();v.plan.stopped=expStop;expBusy=false;const stored=saveExperiments();if(page==='experiment')renderExperiment();notify(stored?'실험 기록을 저장했습니다. 실패하거나 중단한 요청은 자동으로 다시 실행하지 않습니다.':'실험은 끝났지만 기록을 저장하지 못했습니다. 전체 실험 백업을 내려받아 주세요.');}}

function experimentReview(rows){const notes=[];if(rows.some(r=>r.flags?.slice(0,3).some(f=>f.pass===false)))notes.push('문단 수나 문장 수를 지키지 않은 응답이 있습니다. 2차시에서 요청 방법을 고르는 내용을 다시 살펴보세요.');if(rows.some(r=>r.flags?.[3]?.pass===false))notes.push('말투 조건을 어긴 응답이 있습니다. 3차시에서 지시와 예시의 말투가 맞는지 확인해 보세요.');if(rows.some(r=>r.flags?.some(f=>f.pass===null)))notes.push('자동으로 판단하기 어려운 응답이 있습니다. 4차시의 검사 기준을 참고해 직접 확인해 보세요.');return notes.length?'<div class="result"><h3>결과에 따른 복습 추천</h3>'+notes.map(t=>'<p>'+t+'</p>').join('')+'<small>자동 검사에 따른 안내이며 학습 성적은 아닙니다.</small></div>':'';}

function experimentGroups(v){
 const groups=new Map();for(const r of expResults(v)){const key=JSON.stringify([r.model,r.source,r.batch||'수동 입력']);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);}
 return `<details><summary>모델과 실행 회차별 비교</summary><p>이 표는 자동 검사 결과를 모아 보여 줍니다. 모델이나 실행 조건이 다른 결과를 비교할 때는, 그 차이가 프롬프트 때문이라고 단정하지 마세요. 직접 가져온 응답에는 실행 회차 정보가 없습니다.</p>${[...groups].map(([key,runs])=>`<h3>${JSON.parse(key).map(esc).join(' · ')}</h3><div class="tablewrap"><table><tr><th>전달 방식</th><th>전체 기록 / 자동 검사한 응답</th><th>평균 규칙 준수율</th></tr>${Object.entries(EXP_NAMES).map(([k,n])=>{const a=runs.filter(r=>r.condition===k),b=a.filter(r=>r.status==='completed'&&r.flags?.length===4&&r.flags.every(f=>f.pass!==null));return `<tr><th>${n}</th><td>${a.length} / ${b.length}</td><td>${b.length?(100*b.reduce((n,r)=>n+r.flags.filter(f=>f.pass).length,0)/(4*b.length)).toFixed(1)+'%':'—'}</td></tr>`;}).join('')}</table></div>`).join('')}</details>`;
}
function manualReviewUI(r){if(r.status!=='completed'||!r.flags)return '';return `<fieldset data-review="${esc(r.id)}"><legend>직접 다시 검토하기</legend><p>검토 결과를 저장해도 자동 판정과 집계는 바뀌지 않습니다. 직접 판단한 결과와 그 근거를 별도 기록으로 남깁니다.</p>${r.flags.map((f,i)=>`<label>${esc(f.label)} <select data-flag="${i}"><option value="unknown">확인 필요</option><option value="true">지킴</option><option value="false">어김</option></select></label>`).join('')}<label>판단 근거<textarea data-review-reason maxlength="2000"></textarea></label><button data-review-save>검토 기록 저장</button>${(r.reviews||[]).map(x=>`<p>${esc(x.at)} · ${x.flags.map(f=>f===null?'확인 필요':f?'지킴':'어김').join(' / ')}<br>${esc(x.reason)}</p>`).join('')}</fieldset>`;}
function validateExperimentBackup(x){
 if(!x||x.schema!==EXP_KEY||!x.draft||!Array.isArray(x.versions)||!Array.isArray(x.runs))throw Error('프롬프트 실험실의 실험 백업 JSON을 선택해 주세요.');
 const draft=(d,editing=false)=>d&&['task','example','skeleton','reason'].every(k=>typeof d[k]==='string')&&['paragraphs','perParagraph','total'].every(k=>editing?typeof d[k]==='number'&&Number.isFinite(d[k]):Number.isInteger(d[k])&&d[k]>0&&d[k]<=20)&&Number.isInteger(d.repeats)&&d.repeats>=1&&d.repeats<=3&&['요','합니다'].includes(d.style);
 if(!draft(x.draft,true)||x.versions.length>1000||x.runs.length>10000)throw Error('백업의 비교안 형식이나 기록 수를 확인해 주세요.');
 const scalar=t=>t===undefined||typeof t==='string';
 for(const v of x.versions)if(!v||typeof v.at!=='string'||!Number.isFinite(Date.parse(v.at)))throw Error('비교안 날짜가 올바르지 않습니다.');
 for(const r of x.runs)if(!r||!scalar(r.text)||!scalar(r.error)||!scalar(r.at)||!scalar(r.batch)||r.flags!==undefined&&(!Array.isArray(r.flags)||!r.flags.every(f=>f&&typeof f.label==='string'&&scalar(f.detail)&&[true,false,null].includes(f.pass))))throw Error('응답 내용이나 판정 형식이 올바르지 않습니다.');
 const ids=new Set();for(const v of x.versions){if(!v||typeof v.id!=='string'||ids.has(v.id)||!draft(v.draft)||!v.prompts||!Object.keys(EXP_NAMES).every(k=>typeof v.prompts[k]==='string'))throw Error('비교안이 손상되었거나 중복되었습니다.');const expected=experimentPrompts(v.draft);if(experimentProblems(v.draft).length||Object.keys(EXP_NAMES).some(k=>v.prompts[k]!==expected[k]))throw Error('비교안의 조건과 저장된 프롬프트가 서로 다릅니다.');ids.add(v.id);}
 const runs=new Set();for(const r of x.runs){if(!r||typeof r.id!=='string'||runs.has(r.id)||!ids.has(r.version)||!Object.hasOwn(EXP_NAMES,r.condition)||typeof r.model!=='string'||!['api','manual'].includes(r.source)||!['completed','error','incomplete','pending'].includes(r.status))throw Error('응답 기록의 형식이나 비교안 연결이 올바르지 않습니다.');runs.add(r.id);if(r.status==='completed'&&(!Array.isArray(r.flags)||r.flags.length!==4||!r.flags.every(f=>f&&typeof f.label==='string'&&[true,false,null].includes(f.pass))))throw Error('자동 판정 기록이 올바르지 않습니다.');if(r.reviews&&(!Array.isArray(r.reviews)||!r.reviews.every(a=>a&&typeof a.reason==='string'&&typeof a.at==='string'&&Array.isArray(a.flags)&&a.flags.length===4&&a.flags.every(f=>[true,false,null].includes(f)))))throw Error('검토 이력이 올바르지 않습니다.');}
 return {draft:x.draft,versions:x.versions,runs:x.runs,manualDraft:{text:typeof x.manualDraft?.text==='string'?x.manualDraft.text:'',model:typeof x.manualDraft?.model==='string'?x.manualDraft.model:'',condition:Object.hasOwn(EXP_NAMES,x.manualDraft?.condition)?x.manualDraft.condition:'plain'}};
}
function bindExperimentExtras(){
 if(experiments.loadWarning){$('#exp-validation').insertAdjacentHTML?.('afterbegin','<p class="result warning">이 기기의 이전 실험 기록을 읽지 못해 기본값으로 열었습니다. 원본을 내려받아 확인한 뒤 다시 작업해 주세요.</p>');if(expRecoveryRaw){$('#exp-export').insertAdjacentHTML?.('afterend','<button id="exp-recovery">읽지 못한 실험 기록 원본 내려받기</button>');$('#exp-recovery').onclick=()=>download('prompt-lab-experiment-recovery.json',expRecoveryRaw,'application/json');}}
 const anchor=$('#exp-export');if(!anchor?.insertAdjacentHTML)return;
 anchor.insertAdjacentHTML('afterend','<label>실험 백업 불러오기 <input id="exp-restore" type="file" accept=".json,application/json"></label>');
 $('#exp-restore').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(expBusy)throw Error('실험이 끝난 뒤에 불러와 주세요.');if(f.size>10000000)throw Error('백업은 10MB 이하여야 합니다.');const next=validateExperimentBackup(JSON.parse(await f.text()));if(expBusy)throw Error('실험이 끝난 뒤에 불러와 주세요.');if(!confirm(`지금의 실험 기록을 비교안 ${next.versions.length}개, 응답 ${next.runs.length}개가 담긴 백업으로 바꿉니다. 지금 기록이 필요하다면 먼저 백업해 두세요. 불러올까요?`))return;const previous=experiments,previousSelection=expSelected;try{experiments=next;expSelected='';if(page==='experiment')renderExperiment();localStorage.setItem(EXP_KEY,JSON.stringify(next));}catch(error){experiments=previous;expSelected=previousSelection;if(page==='experiment')try{renderExperiment();}catch{}throw error;}notify('실험 기록을 불러왔습니다.');}catch(err){notify('불러오지 못했습니다. 지금 기록은 그대로 남아 있습니다. '+experimentErrorMessage(err,'파일을 읽거나 기록을 저장하지 못했습니다. 파일과 브라우저 저장 공간을 확인해 주세요.'));}finally{e.target.value='';}};
 document.querySelectorAll('[data-review]').forEach(box=>{box.querySelector('[data-review-save]').onclick=()=>{const reason=box.querySelector('[data-review-reason]').value.trim();if(!reason){notify('판단 근거를 적어 주세요.');return;}const r=experiments.runs.find(r=>r.id===box.dataset.review),review={at:expTime(),reason,flags:[...box.querySelectorAll('[data-flag]')].map(el=>el.value==='unknown'?null:el.value==='true')};r.reviews=r.reviews||[];r.reviews.push(review);if(!saveExperiments()){r.reviews.pop();return;}renderExperiment();notify('검토 기록을 저장했습니다.');};});
}
